solution.solution.cpp:
#include <cstddef>
#include <cstdint>
#include <memory>
#include <new>
#include <utility>

class Arena
{
public:
    using Marker = std::size_t;

    explicit Arena(std::size_t capacity)
        : storage{ static_cast<std::byte*>(::operator new(capacity, std::align_val_t{ 64 })) }, size{ capacity } {}
    ~Arena() { ::operator delete(storage, std::align_val_t{ 64 }); }
    Arena(const Arena&) = delete;
    Arena& operator=(const Arena&) = delete;

    void* allocate(std::size_t bytes, std::size_t align = 16)
    {
        const std::size_t start{ (offset + align - 1) & ~(align - 1) };
        if (start > size || bytes > size - start) return nullptr;
        offset = start + bytes;
        return storage + start;
    }

    template <typename T, typename... Args>
    T* make(Args&&... args)
    {
        void* place{ allocate(sizeof(T), alignof(T)) };
        return place ? new (place) T{ std::forward<Args>(args)... } : nullptr;
    }

    Marker mark() const { return offset; }
    void rewind(Marker m) { if (m <= offset) offset = m; }
    void reset() { offset = 0; }
    std::size_t used() const { return offset; }
    std::size_t capacity() const { return size; }

private:
    std::byte* storage;
    std::size_t size;
    std::size_t offset{ 0 };
};

unitTests:
#include <cstdint>
static std::uintptr_t addr(const void* p) { return reinterpret_cast<std::uintptr_t>(p); }
struct Vec3 { float x, y, z; };

TEST("bump allocation") {
    Arena arena{ 256 };
    void* a{ arena.allocate(10) };
    void* b{ arena.allocate(10) };
    CHECK(a != nullptr); CHECK(b != nullptr);
    CHECK_EQ(addr(b) - addr(a), 16u);
    CHECK_EQ(arena.used(), 26u);
    void* c{ arena.allocate(1, 1) };
    CHECK_EQ(addr(c) - addr(a), 26u);
    CHECK_EQ(arena.capacity(), 256u);
}
TEST("alignment") {
    Arena arena{ 256 };
    arena.allocate(3, 1);
    void* d{ arena.allocate(8, 8) };
    CHECK_EQ(addr(d) % 8, 0u);
    void* e{ arena.allocate(1, 64) };
    CHECK_EQ(addr(e) % 64, 0u);
    CHECK_EQ(arena.used(), 65u);
}
TEST("full arenas refuse and do not move") {
    Arena arena{ 64 };
    CHECK(arena.allocate(60) != nullptr);
    CHECK(arena.allocate(8) == nullptr);
    CHECK_EQ(arena.used(), 60u);
    CHECK(arena.allocate(4, 4) != nullptr);
    CHECK(arena.allocate(1, 1) == nullptr);
    CHECK(Arena{ 16 }.allocate(1000) == nullptr);
}
TEST("markers and reset") {
    Arena arena{ 256 };
    arena.allocate(32);
    const Arena::Marker m{ arena.mark() };
    void* temp{ arena.allocate(100) };
    arena.rewind(m);
    CHECK_EQ(arena.used(), 32u);
    CHECK(arena.allocate(100) == temp);
    arena.reset();
    CHECK_EQ(arena.used(), 0u);
}
TEST("constructing objects in place") {
    Arena arena{ 128 };
    Vec3* v{ arena.make<Vec3>(1.0f, 2.0f, 3.0f) };
    CHECK(v != nullptr);
    CHECK_EQ(v->y, 2.0f);
    double* d{ arena.make<double>(2.5) };
    CHECK_EQ(*d, 2.5);
    CHECK_EQ(addr(d) % alignof(double), 0u);
    Arena tiny{ 8 };
    CHECK(tiny.make<Vec3>(0.0f, 0.0f, 0.0f) == nullptr);
}

